package com.tripdeck.app;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import android.hardware.*;import android.view.*;import android.webkit.*;import org.json.*;import java.io.*;
public class MainActivity extends Activity implements SensorEventListener {
 WebView web; SensorManager sm; String pending; volatile boolean recalibrate=true; float[] baseline=new float[9]; long lastMotion=0; float[] matrix=new float[9], adjusted=new float[9], angles=new float[3];
 public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(Build.VERSION.SDK_INT>=35){getWindow().getDecorView().setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets a=i.getInsets(WindowInsets.Type.systemBars());v.setPadding(a.left,a.top,a.right,a.bottom);return i;});}web=new WebView(this);setContentView(web);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.addJavascriptInterface(new Bridge(),"Native");web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){if(r.getUrl().toString().equals("https://tripdeck.local/index.html"))try{return new WebResourceResponse("text/html","UTF-8",getAssets().open("index.html"));}catch(Exception ignored){}if(r.getUrl().toString().equals("https://tripdeck.local/offline-map.json"))try{return new WebResourceResponse("application/json","UTF-8",getAssets().open("offline-map.json"));}catch(Exception ignored){}return null;}});web.setWebChromeClient(new WebChromeClient());web.loadUrl("https://tripdeck.local/index.html");sm=getSystemService(SensorManager.class);}
 void gps(){if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},4);return;}startForegroundService(new Intent(this,GpsService.class));if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},5);}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==4&&checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED)gps();else if(r==4)web.evaluateJavascript("document.getElementById('status').textContent='Precise location permission required';",null);}
 class Bridge { @JavascriptInterface public void calibrate(){recalibrate=true;} @JavascriptInterface public void gps(){runOnUiThread(()->MainActivity.this.gps());} @JavascriptInterface public boolean running(){return GpsService.running;} @JavascriptInterface public void recording(boolean b){GpsService.recording=b;} @JavascriptInterface public String drain(){synchronized(GpsService.queue){JSONArray a=new JSONArray(GpsService.queue);GpsService.queue.clear();return a.toString();}} @JavascriptInterface public String latest(){synchronized(GpsService.queue){return GpsService.latest==null?"null":GpsService.latest.toString();}} @JavascriptInterface public void stop(){runOnUiThread(()->stopService(new Intent(MainActivity.this,GpsService.class)));} @JavascriptInterface public void export(String name,String data){runOnUiThread(()->{pending=data;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/octet-stream").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(i,9);});} @JavascriptInterface public void recovery(){try{File f=new File(getFilesDir(),"recovery.csv");if(!f.exists())return;ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=new FileInputStream(f)){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);}export("tripdeck-recovery.csv","epoch_ms,latitude,longitude,altitude_m,speed_mps,heading,accuracy_m\n"+out.toString("UTF-8"));}catch(Exception ignored){}} }
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==9&&c==RESULT_OK&&d!=null&&pending!=null)try(OutputStream o=getContentResolver().openOutputStream(d.getData())){o.write(pending.getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception e){new AlertDialog.Builder(this).setMessage("Export failed: "+e.getMessage()).setPositiveButton("OK",null).show();}pending=null;}
 protected void onResume(){super.onResume();if(sm!=null){Sensor s=sm.getDefaultSensor(Sensor.TYPE_GAME_ROTATION_VECTOR);if(s!=null)sm.registerListener(this,s,SensorManager.SENSOR_DELAY_UI);}} protected void onPause(){if(sm!=null)sm.unregisterListener(this);super.onPause();}
 public void onAccuracyChanged(Sensor s,int a){} public void onSensorChanged(SensorEvent e){SensorManager.getRotationMatrixFromVector(matrix,e.values);int rot=getWindowManager().getDefaultDisplay().getRotation();int x=SensorManager.AXIS_X,y=SensorManager.AXIS_Y;if(rot==1){x=SensorManager.AXIS_Y;y=SensorManager.AXIS_MINUS_X;}else if(rot==2){x=SensorManager.AXIS_MINUS_X;y=SensorManager.AXIS_MINUS_Y;}else if(rot==3){x=SensorManager.AXIS_MINUS_Y;y=SensorManager.AXIS_X;}SensorManager.remapCoordinateSystem(matrix,x,y,adjusted);if(recalibrate){System.arraycopy(adjusted,0,baseline,0,9);recalibrate=false;}long now=SystemClock.elapsedRealtime();if(now-lastMotion<50)return;lastMotion=now;float[] relative=new float[9];for(int i=0;i<3;i++)for(int j=0;j<3;j++)for(int k=0;k<3;k++)relative[i*3+j]+=baseline[k*3+i]*adjusted[k*3+j];double pitch=Math.toDegrees(Math.atan2(-relative[7],relative[8]));double roll=Math.toDegrees(Math.atan2(relative[6],relative[8]));web.evaluateJavascript("window.nativeMotion&&nativeMotion("+pitch+","+roll+")",null);}
}
